const thunderLampSheet=new Image();thunderLampSheet.assetSrc='assets/thunder-lamp-v1.png';
function beginThunderLamp(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'thunderBreakableTether',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},fired:false};}
function breakThunderLamp(e){e.attack=null;e.state='idle';e.thunderLampOpen=2;e.t=1.2;playSound('impact',e.x,e.y);}
function thunderLampFactor(e){return e.species==='r6e6'&&e.hp>0&&e.thunderLampOpen>0&&!e.dotTick?1.5:1;}
const thunderLampHitBase=hit;hit=(e,d)=>thunderLampHitBase(e,d*thunderLampFactor(e));
const thunderLampAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e6')return thunderLampAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);if(e.thunderLampOpen>0){e.thunderLampOpen=Math.max(0,Math.round((e.thunderLampOpen-dt)*1e6)/1e6);e.attack=null;e.state='idle';e.t=1.2;return;}let a=e.attack;
 if(a?.pattern!=='thunderBreakableTether'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=320&&clear){beginThunderLamp(e);return;}e.state='idle';if(d>800&&!e.aware||d<=240&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,70*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){if(!a.fired)breakThunderLamp(e);else{e.attack=null;e.state='idle';e.t=1.2;}return;}
 if(!a.fired&&(dist(p,a.origin)>420+1e-8||!lineClear(a.origin,p))){breakThunderLamp(e);return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=1.8){a.fired=true;e.struck=true;hurt(84);burst(p.x,p.y,35,'#fff0b5');playSound('impact',e.x,e.y);}if(e.elapsed>=2.4){e.attack=null;e.state='idle';e.t=3.2;}
};
const thunderLampDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e6'||!thunderLampSheet.complete||!thunderLampSheet.naturalWidth||!thunderLampSheet.naturalHeight)return thunderLampDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0||e.thunderLampOpen>0)f={row:2,col:3};else if(e.attack?.pattern==='thunderBreakableTether')f={row:2,col:e.elapsed<.5?0:e.elapsed<1.8?1:e.elapsed<2?2:3};let q=project(e.x,e.y),sw=thunderLampSheet.naturalWidth/4,sh=thunderLampSheet.naturalHeight/3,w=210,h=w*sh/sw,anchor=[.91,.88,.88][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,thunderLampSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(thunderLampSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const thunderLampSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e6'?130:thunderLampSizeBase(e);
const thunderLampGroundBase=drawGroundEffects;drawGroundEffects=()=>{thunderLampGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e6'):enemies)){if(e.species!=='r6e6'||e.hp<=0)continue;let a=e.attack;if(e.thunderLampOpen>0&&visibleAt(e.x,e.y)){groundRing(e.x,e.y,45,'#99e9db',2);continue;}if(a?.pattern!=='thunderBreakableTether'||e.elapsed>=2||!visibleAt(e.x,e.y)&&!visibleAt(p.x,p.y))continue;if(!a.fired)groundRing(a.origin.x,a.origin.y,420,'#9cc4dd',1);groundRing(p.x,p.y,25,a.fired?'#fff4c5':'#e5b97a',2);}};
const thunderLampEffectsBase=drawEffects;drawEffects=()=>{thunderLampEffectsBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e6'):enemies)){let a=e.attack;if(e.species!=='r6e6'||e.hp<=0||a?.pattern!=='thunderBreakableTether'||e.elapsed>=2||!visibleAt(e.x,e.y)&&!visibleAt(p.x,p.y))continue;let from=project(a.origin.x,a.origin.y),to=project(p.x,p.y);ctx.save();ctx.strokeStyle=a.fired?'#fff4c5':'#e5b97a';ctx.lineWidth=a.fired?5:2;ctx.beginPath();ctx.moveTo(from.x,from.y-45);ctx.lineTo(to.x,to.y-25);ctx.stroke();ctx.restore();}};
